<?php
declare(strict_types=1); require_once __DIR__.'/../includes/functions.php'; require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('admin/reservations.php');verify_csrf();$id=(int)post('id');$action=post('action');$pdo=db();
try{$pdo->beginTransaction();$s=$pdo->prepare('SELECT rs.*,b.status book_status,b.rental_price_per_day FROM reservations rs JOIN books b ON b.id=rs.book_id WHERE rs.id=? FOR UPDATE');$s->execute([$id]);$r=$s->fetch();if(!$r)throw new RuntimeException('ไม่พบรายการจอง');
if($action==='approve'&&$r['status']==='pending'){$pdo->prepare("UPDATE reservations SET status='approved',approved_at=NOW() WHERE id=?")->execute([$id]);$pdo->prepare("UPDATE books SET status='reserved' WHERE id=?")->execute([$r['book_id']]);$msg='อนุมัติการจองแล้ว';}
elseif($action==='reject'&&$r['status']==='pending'){$pdo->prepare("UPDATE reservations SET status='rejected' WHERE id=?")->execute([$id]);$pdo->prepare("UPDATE books SET status='available' WHERE id=?")->execute([$r['book_id']]);$msg='ปฏิเสธการจองแล้ว';}
elseif($action==='convert'&&$r['status']==='approved'&&$r['book_status']==='reserved'){$total=rental_fee((float)$r['rental_price_per_day'],(int)$r['rental_days']);$pdo->prepare("INSERT INTO rentals(user_id,book_id,reservation_id,source,rental_days,rental_price_per_day_at_time,rental_total,borrowed_at,due_date,status) VALUES(?,?,?,'online_reservation',?,?,?,NOW(),?,'borrowed')")->execute([$r['user_id'],$r['book_id'],$id,$r['rental_days'],$r['rental_price_per_day'],$total,$r['due_date']]);$pdo->prepare("UPDATE reservations SET status='converted',converted_at=NOW() WHERE id=?")->execute([$id]);$pdo->prepare("UPDATE books SET status='borrowed' WHERE id=?")->execute([$r['book_id']]);$msg='เริ่มการเช่าสำเร็จ';}
else throw new RuntimeException('สถานะรายการไม่รองรับการทำงานนี้');log_activity($action,'reservation',$id);$pdo->commit();flash($msg);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');}redirect('admin/reservations.php');
